<dialog id="request-feedback" class="auth-modal ui-request-dialog" aria-labelledby="request-feedback-title" aria-describedby="request-feedback-description">
    <h2 id="request-feedback-title">Status belum pasti</h2>
    <p id="request-feedback-description" class="auth-muted"></p>
    <p class="auth-hint">Cek Status memuat ulang data server tanpa mengirim ulang tindakan. Jika hasil reset password tidak diterima, periksa akun dan lakukan verifikasi manual sebelum tindakan baru.</p>
    <div class="auth-modal-actions"><button type="button" class="button button-lime" data-check-status>Cek Status</button><button type="button" class="auth-secondary" data-dismiss-feedback>Tutup</button></div>
</dialog>
